UPDATE bank_accounts
SET imported_at = COALESCE(imported_at, CURRENT_TIMESTAMP),
    is_primary = CASE WHEN #{makePrimary} THEN TRUE ELSE is_primary END
WHERE user_id = #{userId}
  AND bank_account_id = #{accountId}
  AND registered_person_id IS NULL

mapper.select:
SELECT COUNT(*)
FROM bank_accounts
WHERE user_id = #{userId}
  AND registered_person_id = #{registeredPersonId}
  AND bank_code = #{bankCode}
  AND REPLACE(account_number, '-', '') = #{normalizedAccountNumber}

  AND bank_account_id != #{excludedAccountId}

mapper.update:
UPDATE registered_persons
SET name = #{name},
    relationship = #{relationship},
    profile_image_key = #{profileImageKey}
WHERE registered_person_id = #{registeredPersonId}
  AND user_id = #{userId}

UPDATE bank_accounts
SET bank_code = #{bankCode},
    bank_name = #{bankName},
    account_number = #{accountNumber},
    account_alias = #{accountAlias}
WHERE bank_account_id = #{accountId}
  AND user_id = #{userId}
  AND registered_person_id = #{registeredPersonId}

